CSS = CSS.replace('"""\n', '"""\n') if False else CSS
CSS_ALL = CSS + CSS2
def sheet_page(name, title, *phones, width=1700):
    open(name+'.html','w').write(f'<!doctype html><meta charset="utf-8"><title>{title}</title><style>{CSS_ALL}</style><body>{"".join(phones)}</body>')
def navbar(t, sub='', left=('back',None), right=(None,None)):
    l = f'<div class="ic">{ic(left[0],21,2.2)}</div>' if left[0] else (f'<div class="ic" style="width:auto;font-size:15px">{left[1]}</div>' if left[1] else '<div class="ic"></div>')
    r = f'<div class="ic">{ic(right[0],20)}</div>' if right[0] else (f'<div class="ic" style="width:auto;font-size:15px;font-weight:700">{right[1]}</div>' if right[1] else '<div class="ic"></div>')
    return f'<div class="nav">{l}<div class="t"><b>{t}</b>{f"<small>{sub}</small>" if sub else ""}</div>{r}</div>'
def sheet(title, body, sub=''): return f'<div class="sheetwrap"><div class="scrim"></div><div class="sheet"><div class="grab"></div><div class="sh-t">{title}{f"<small>{sub}</small>" if sub else ""}</div>{body}</div></div>'
