chips = lambda items, on=0: '<div class="chips">'+''.join(f'<span class="chipr{" on" if k==on else ""}">{t}</span>' for k,t in enumerate(items))+'</div>'
seg = lambda items, on=0: '<div class="segm">'+''.join(f'<span class="{"on" if k==on else ""}">{t}</span>' for k,t in enumerate(items))+'</div>'
fld = lambda lab, val: f'<div class="fld"><small>{lab}</small><div class="inp">{val}</div></div>'
fcard = lambda n, m, pages=6: f'<div class="fcard"><div class="thumb"><div class="pg">{L(pages)}</div></div><div style="flex:1"><b>{n}</b><small style="display:block;color:var(--mut);font-size:12.5px">{m}</small></div><span style="color:var(--acc);font-weight:600;font-size:14px">Change</span></div>'
