c5 = phone('Import · single pages or book spreads', f'<div class="scroll"><div class="title">PDFs</div><div class="group">{"".join(row(*r) for r in rows[:3])}</div></div>{tabs("PDFs")}' + sheet('Import images', seg(['Single page','Book spread'],1)+'<p style="color:var(--mut);font-size:13px;padding:0 8px 12px">One photo of an open book becomes two pages, left then right. Imported spreads open a quick review first.</p><div class="btnp">'+ic("img",20,2)+' Choose photos</div><div class="btns" style="margin-top:10px">Close</div>'))
