sel = phone('Pages · selecting', f'{navbar("3 selected","",("x",None),(None,"Select all"))}<div class="scroll" style="padding-top:98px"><div class="grid">{selcard("1")}{selcard("2",False)}<div class="card wide"><div class="pg" style="flex:1">{L(10)}</div><div class="pg" style="flex:1">{L(10)}</div><span class="n">3–4</span><span class="check on">{ic("check",13,3)}</span></div>{selcard("5")}</div></div><div class="bar"><div class="cap" style="flex:1;display:flex">' + ''.join(f'<div style="display:flex;flex-direction:column;align-items:center;gap:2px;font-size:10.5px;color:{"#ff3b30" if t=="Delete" else "var(--acc)"};flex:1">{ic(i,21)}{t}</div>' for i,t in [("crop","Crop"),("rot","Rotate"),("sliders","Filter"),("trash","Delete")]) + '</div></div>')
