# ---------------------------------------------------------------- 7 DESKTOP
def dwin(title, body, active='PDFs', cls=''):
    side = '<h4>PDF Scanner</h4>' + ''.join(f'<div class="{"on" if n==active else ""}">{ic(i,18)}{n}</div>' for i,n in [('pdf','PDFs'),('tools','Tools'),('gear','Settings')])
    return f'<div class="col"><h3>{title}</h3><div class="dwin {cls}"><div class="dtop"><b></b><b></b><b></b><span style="margin:auto;font-size:12px;color:var(--mut)">saitejavoonna.github.io/pdf-scanner</span></div><div class="dbody"><div class="side">{side}</div><div class="dmain">{body}</div></div></div></div>'
dr = lambda n,m: f'<div class="row"><div class="thumb"><div class="pg">{L(6)}</div></div><div><b>{n}</b><small>{m}</small></div><span class="chev">{ic("chev",17,2.2)}</span></div>'
dhome = dwin('Desktop · PDFs', f'<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:12px"><div class="title" style="padding:0;font-size:28px">PDFs</div><div style="display:flex;gap:10px;align-items:center"><div class="search" style="margin:0;width:220px">{ic("search",16)} Search</div><div class="btnp" style="height:40px;padding:0 20px;border-radius:20px">{ic("cam",18,2)} Scan</div></div></div><div class="cont" style="margin:0 0 14px"><div class="thumb"><div class="pg">{L(4)}</div></div><div><b>Continue scanning</b><small style="display:block;color:var(--mut);font-size:12.5px">4 pages · auto-saved</small></div><div class="btn">Open</div></div><div class="group" style="margin:0">{"".join(dr(*r) for r in rows)}</div>')
dpages = dwin('Desktop · open PDF', f'<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:12px"><div><div class="title" style="padding:0;font-size:24px">Biology notes ch4</div><div style="color:var(--mut);font-size:13px">17 pages · 2 to check</div></div><div style="display:flex;gap:10px"><div class="btns" style="height:40px;padding:0 18px">{ic("plus",18)} Add pages</div><div class="btnp" style="height:40px;padding:0 20px;border-radius:20px">Make PDF</div></div></div><div style="display:grid;grid-template-columns:repeat(5,1fr);gap:12px">{"".join(f"<div class=card style=height:150px><div class=pg>{L(10)}</div><span class=n>{i}</span></div>" for i in range(1,11))}</div>')
